package main
import ("fmt"; "net/http"; "net/http/httptest")
// ServeMux implements http.Handler.
func main(){mux:=http.NewServeMux();mux.HandleFunc("GET /health",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json");fmt.Fprintln(w,`{"status":"ok"}`)});r:=httptest.NewRequest("GET","/health",nil);rec:=httptest.NewRecorder();mux.ServeHTTP(rec,r);fmt.Println(rec.Code,rec.Body.String())}
